func TestParse(t *testing.T) {
  tests := []struct{ name, in string; want Version; wantErr bool }{
    {"plain", "1.2.3", Version{1,2,3}, false},
    {"bad", "x", Version{}, true},
  }
  for _, tc := range tests {
    t.Run(tc.name, func(t *testing.T) {
      // Arrange
      // Act
      got, err := Parse(tc.in)
      // Assert
      if (err != nil) != tc.wantErr || got != tc.want { t.Fatalf("%s: %v %v", tc.in, got, err) }
    })
  }
}

